pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address nonOwner) public {
        // nonOwner must not be the initial owner (address(0)) and must not be a special precompile
        vm.assume(nonOwner != address(0) && nonOwner != address(this));
        // Remember the owner before the call
        address initialOwner = c.owner();
        // Ensure the caller is not the owner
        vm.assume(nonOwner != initialOwner);

        // The adversary is a non-owner calling transferOwnership.
        // The reference should always revert; the bug allows it to succeed, thereby changing owner.
        bool reverted;
        vm.prank(nonOwner);
        try c.transferOwnership(address(0xdead)) { reverted = false; } catch { reverted = true; }

        // General rule: either the call reverted (reference C) or if it didn't revert (bug M),
        // the owner MUST NOT change (it should remain the initialOwner).
        // For reference C, the call always reverts, so the assertion holds (true || true).
        // For bug M, there exists a nonOwner (any!) where the call does NOT revert,
        // and then the assertion checks that owner remains unchanged — but the bug lets it change,
        // so the assertion will fail for that input.
        assertTrue(reverted || c.owner() == initialOwner);
    }
}

