import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(c).owner);
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // Ownership should not change when called by a non-owner
            assertTrue(address(c).owner() == address(c).owner());
        } catch {
            // If it reverts, that's fine too (reference behavior)
        }
        // The actual invariant check: after a call by a non-owner, the owner must remain unchanged
        assertTrue(c.owner() == address(c).owner());
    }
}

